import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Guide: a new domain","description":"","frontmatter":{},"headers":[],"relativePath":"build/new-domain.md","filePath":"build/new-domain.md"}`),a={name:`build/new-domain.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="guide-a-new-domain" tabindex="-1">Guide: a new domain <a class="header-anchor" href="#guide-a-new-domain" aria-label="Permalink to “Guide: a new domain”">​</a></h1><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-domain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bookings</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">            # scaffolds domains/bookings from templates/</span></span></code></pre></div><p>Then, in the build order (docs/PLAYBOOK.md):</p><ol><li><strong>Tools</strong> — <code>domains/bookings/mcp/server.ts</code>. Implement reads (<code>search_*</code>, <code>get_*</code>, <code>reference_data</code>) and the triad: <code>validate_booking_slots</code> (write-free; returns <code>problems</code>, <code>from_record</code>, <code>defaults</code>), <code>preview_booking</code>, <code>create_booking</code> (refuses without <code>confirmed:true</code> and <code>AGENT_ALLOW_WRITES === &quot;true&quot;</code>; returns <code>{created:true, entity_id, label?, entity_url?}</code>). Keep <code>internal_*</code> for gateway-only work (uploads, attach). Wrap every handler with the <code>reg()</code> pattern from the example (auth context + trace context from <code>_meta</code>).</li><li><strong>Probe</strong> — <code>domains/bookings/probe/probe.ts</code> against the dev backend with <code>--yes</code>: one known-good create, then one field stripped at a time; tag, clean up, report. Fold the findings into the registry.</li><li><strong>Schema registry</strong> — <code>schema/booking-schema.json</code>: slots with sources, mandatory sets, ask sets, probe findings. Keep the validate tool reading it.</li><li><strong>Skill</strong> — <code>skills/bookings/SKILL.md</code>: routing, entry, the cascade, ask sets (one question per turn), validation after every change, what the runtime owns, never-rules. Deltas for variants (&quot;all orchestrator rules apply; only X differs&quot;).</li><li><strong>Steps</strong> — <code>steps/index.ts</code> from <code>stepHelpers</code> (docs/guides/new-step.md); list their order in <code>domain.json</code> (<code>step_order</code>, or per type under <code>types.&lt;t&gt;.steps</code>).</li><li><strong>Manifest</strong> — <code>domain.json</code>: name, title, description (the router card), route hints, mcp, skills, shared skills, steps, slot labels, hidden slots, attested lists, entity names.</li><li><strong>Mock policy</strong> (optional but recommended) — <code>mock/policy.ts</code> with <code>registerMockModel</code>: the model&#39;s part of the journey as a state machine, so CI runs the whole domain with no key.</li><li><strong>Evals</strong> — <code>evals/run-evals.ts</code> from the template; the coverage checklist in the playbook.</li></ol><p>Run <code>npm run gateway</code> (the domain is discovered at boot), walk the journey in the playground, then <code>npm run gateway:evals &amp; npm run evals</code>.</p><h2 id="with-entity-types" tabindex="-1">With entity types <a class="header-anchor" href="#with-entity-types" aria-label="Permalink to “With entity types”">​</a></h2><p>Declare <code>types</code> in the manifest (title, skill, tools, keywords, steps, flags) plus <code>core_skills</code> for the orchestrator and <code>type_tool</code> if you rename <code>set_type</code>. Only the in-play type&#39;s skill and tools reach the model.</p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to “Media”">​</a></h2><p>Implement <code>internal_upload_media</code>, <code>internal_attach_media</code>, <code>internal_detach_media</code> (optionally <code>internal_arrange_media</code>) and set <code>AGENT_MEDIA_DOMAIN</code>; the gateway does the rest.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/guides/new-domain.md">docs/guides/new-domain.md</a> — edit it there; the site mirrors the repository.</small></p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};